-- Step 1 of 5 for orders.public_id. Transactional.
-- Both statements are catalog-only: no scan, no rewrite. The default is set separately because a
-- volatile default in ADD COLUMN (gen_random_uuid()) would rewrite all ~80M rows under ACCESS EXCLUSIVE.
SET LOCAL lock_timeout = '5s';
ALTER TABLE orders ADD COLUMN public_id uuid;
ALTER TABLE orders ALTER COLUMN public_id SET DEFAULT gen_random_uuid();

Write /home/dev/project/migrations/0005_orders_public_id_backfill.sql
-- migrate:no-transaction
-- Step 2 of 5 for orders.public_id. Backfills existing rows.
--
-- Walks the primary key in chunks and COMMITs after each one, so row locks are released every
-- chunk and no transaction stays open for the whole backfill. The default from 0004 is already in
-- place, so rows inserted while this runs are filled by the database. Rerunning is safe: rows that
-- already have a value are skipped. If the run stops partway, the next run picks up where it left off.
--
-- lock_timeout bounds how long one chunk may wait on a row lock held by a payment or fulfilment
-- transaction. A timeout fails the migration; rerun it.
SET lock_timeout = '5s';

DO $$
DECLARE
  chunk constant bigint := 5000;
  lower_key bigint := 0;
  upper_bound bigint;
BEGIN
  SELECT coalesce(max(id), 0) INTO upper_bound FROM orders;
  WHILE lower_key <= upper_bound LOOP
    UPDATE orders SET public_id = gen_random_uuid()
    WHERE id >= lower_key AND id < lower_key + chunk AND public_id IS NULL;
    lower_key := lower_key + chunk;
    COMMIT;
  END LOOP;
END
$$;

RESET lock_timeout;

