-- Step 4 of 5 for orders.public_id. Transactional.
-- Attaches the index built in 0006 as a unique constraint. This is catalog-only, so the
-- ACCESS EXCLUSIVE lock is held only briefly.
SET LOCAL lock_timeout = '5s';
ALTER TABLE orders ADD CONSTRAINT orders_public_id_key UNIQUE USING INDEX orders_public_id_key;

