-- Step 5 of 5 for orders.public_id (part 2 of 2). Transactional, and deliberately a separate file.
-- Within one transaction, VALIDATE would run under the ACCESS EXCLUSIVE lock taken by 0008.
-- VALIDATE scans the table under SHARE UPDATE EXCLUSIVE, which does not block reads or writes.
SET LOCAL lock_timeout = '5s';
ALTER TABLE orders VALIDATE CONSTRAINT orders_public_id_not_null;

